<template><header class="h-16 bg-white border-b px-4 sm:px-6 flex items-center justify-between"><RouterLink to="/" class="font-bold text-xl text-indigo-600">Delcom Auction</RouterLink><div class="flex items-center gap-3"><RouterLink to="/profile" class="hidden sm:block text-sm font-medium text-slate-600">{{auth.user?.name||'Profil'}}</RouterLink><button class="rounded-lg bg-red-50 text-red-600 px-3 py-2 text-sm font-semibold" @click="logout">Keluar</button></div></header></template>
<script setup>import {useRouter} from 'vue-router';import {useAuthStore} from '../../auth/states/authStore';import {showConfirmDialog} from '../../../helpers/toolsHelper';const router=useRouter();const auth=useAuthStore();async function logout(){const r=await showConfirmDialog('Keluar?','Sesi kamu akan diakhiri.');if(r.isConfirmed){await auth.logout();router.push('/auth/login')}}
</script>
